def grid(s,label):
 m=re.search(re.escape(label)+r' \(\d+x\d+\):\n((?:[0-9 ]+\n)+)',s)
 return [list(map(int,x.split())) for x in m.group(1).strip().splitlines()] if m else None
for num,mid in enumerate((5,49,57,163),1):
 s=ms[mid]; g=grid(s,f'Demo pair {num} input'); out=grid(s,f'Demo pair {num} output')
 bg=collections.Counter(v for row in g for v in row).most_common(1)[0][0]; H,W=len(g),len(g[0]); seen=set(); print('DEMO',num,'bg',bg)
 for y in range(H):
  for x in range(W):
   col=g[y][x]
   if col==bg or (y,x) in seen: continue
   st=[(y,x)]; seen.add((y,x)); cells=[]
   while st:
    a,b=st.pop(); cells.append((a,b))
    for aa,bb in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=aa<H and 0<=bb<W and g[aa][bb]==col and (aa,bb) not in seen: seen.add((aa,bb)); st.append((aa,bb))
   y0=min(a for a,b in cells); y1=max(a for a,b in cells); x0=min(b for a,b in cells); x1=max(b for a,b in cells)
   border={(y0,b) for b in range(x0,x1+1)}|{(y1,b) for b in range(x0,x1+1)}|{(a,x0) for a in range(y0,y1+1)}|{(a,x1) for a in range(y0,y1+1)}
   if set(cells)==border and y1-y0>=2 and x1-x0>=2:
    fills=collections.Counter(out[a][b] for a in range(y0+1,y1) for b in range(x0+1,x1)); print(' ',col,'at',(y0,x0),'size',(y1-y0+1,x1-x0+1),'fill',dict(fills))

