    if not m: raise ValueError('missing '+start)
    return [[int(v) for v in line.split()] for line in m.group(1).strip().splitlines()]
def components(g,bg):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for r in range(h):
      for x in range(w):
       if g[r][x]==bg or (r,x) in seen: continue
       color=g[r][x]; st=[(r,x)]; seen.add((r,x)); cells=[]
       while st:
        a,b=st.pop(); cells.append((a,b))
        for q,t in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
         if 0<=q<h and 0<=t<w and (q,t) not in seen and g[q][t]==color:
