       r0=min(a for a,b in cells); r1=max(a for a,b in cells); c0=min(b for a,b in cells); c1=max(b for a,b in cells)
       side=r1-r0+1
       border={(r0,j) for j in range(c0,c1+1)}|{(r1,j) for j in range(c0,c1+1)}|{(i,c0) for i in range(r0,r1+1)}|{(i,c1) for i in range(r0,r1+1)}
       if len(cells)==len(border) and set(cells)==border and side>=3 and c1-c0+1==side:
