import sqlite3, re
p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-high-ws0/frozen/seen/play/users/u014/system/state/hermes/state.db'
c=sqlite3.connect(f'file:{p}?mode=ro',uri=True)
s='8b955a59-c7c3-4d6d-ada5-b812c78a0637'
msgs=dict((i,txt) for i,txt in c.execute('select id,content from messages where session_id=? and role="user"',(s,)))
def grid_lines(block):
    return [[int(v) for v in line.split()] for line in block.strip().splitlines() if line.strip()]
# parse demos in user feedback messages
pairs=[]
for mid,txt in sorted(msgs.items()):
    for m in re.finditer(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)\nDemo pair \1 output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance\.|\Z)',txt,re.S):
        n=int(m.group(1)); gi=grid_lines(m.group(4)); go=grid_lines(m.group(5))
        pairs.append((n,gi,go))
print('demo pairs parsed:',[(n,len(a),len(a[0]),len(b)) for n,a,b in pairs])
# connected components, identify exact rectangular perimeters and verify fill parity
from collections import Counter, deque
for n,g,o in pairs:
    h,w=len(g),len(g[0]); bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    seen=set(); frames=[]
    for y in range(h):
      for x in range(w):
        col=g[y][x]
        if col==bg or (y,x) in seen: continue
        q=[(y,x)]; seen.add((y,x)); cells=[]
        while q:
          a,b=q.pop(); cells.append((a,b))
          for aa,bb in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
            if 0<=aa<h and 0<=bb<w and (aa,bb) not in seen and g[aa][bb]==col:
              seen.add((aa,bb));q.append((aa,bb))
        y0=min(a for a,b in cells);y1=max(a for a,b in cells);x0=min(b for a,b in cells);x1=max(b for a,b in cells)
        border={(y0,b) for b in range(x0,x1+1)}|{(y1,b) for b in range(x0,x1+1)}|{(a,x0) for a in range(y0,y1+1)}|{(a,x1) for a in range(y0,y1+1)}
        if len(cells)==len(border) and set(cells)==border:
          diffs={o[a][b] for a in range(y0+1,y1) for b in range(x0+1,x1) if o[a][b]!=g[a][b]}
          if diffs: frames.append((col,(y0,x0),y1-y0+1,x1-x0+1,diffs))
    print('demo',n,'frames/fills:',frames,'parity all exact:',all(d==({2} if hh%2==0 else {7}) for _,_,hh,ww,d in frames if hh==ww))
# test grid, apply parity
text=msgs[1]
mt=re.search(r'Test input \((\d+)x(\d+)\):\n(.*?)(?=\nWrong attempts used:)',text,re.S)
t=grid_lines(mt.group(3));h,w=len(t),len(t[0]); bg=Counter(v for row in t for v in row).most_common(1)[0][0]
out=[r[:] for r in t]; seen=set();summary=[]
for y in range(h):
 for x in range(w):
  col=t[y][x]
  if col==bg or (y,x) in seen: continue
  q=[(y,x)];seen.add((y,x));cells=[]
  while q:
   a,b=q.pop();cells.append((a,b))
   for aa,bb in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
    if 0<=aa<h and 0<=bb<w and (aa,bb) not in seen and t[aa][bb]==col:seen.add((aa,bb));q.append((aa,bb))
  y0=min(a for a,b in cells);y1=max(a for a,b in cells);x0=min(b for a,b in cells);x1=max(b for a,b in cells)
  border={(y0,b) for b in range(x0,x1+1)}|{(y1,b) for b in range(x0,x1+1)}|{(a,x0) for a in range(y0,y1+1)}|{(a,x1) for a in range(y0,y1+1)}
  if len(cells)==len(border) and set(cells)==border:
   fill=2 if (y1-y0+1)%2==0 else 7
   for a in range(y0+1,y1):
    for b in range(x0+1,x1):out[a][b]=fill
   summary.append({'color':col,'box':[y0,y1,x0,x1],'size':[y1-y0+1,x1-x0+1],'fill':fill})
print('test frames:',summary)
print('OUTPUT GRID:')
for row in out: print(' '.join(map(str,row)))

