{"output": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for y in range(h):
        for x in range(w):
            c = grid[y][x]
            if c == bg or (y, x) in seen:
                continue
            stack = [(y, x)]
            seen.add((y, x))
            cells = []
            while stack:
                a, b = stack.pop()
                cells.append((a, b))
                for aa, bb in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0 <= aa < h and 0 <= bb < w and (aa,bb) not in seen and grid[aa][bb] == c:
                        seen.add((aa,bb)); stack.append((aa,bb))
            y0, y1 = min(a for a,b in cells), max(a for a,b in cells)
            x0, x1 = min(b for a,b in cells), max(b for a,b in cells)
            if y1-y0 < 2 or x1-x0 < 2:
                continue
            border = set((y0,b) for b in range(x0,x1+1)) | set((y1,b) for b in range(x0,x1+1)) | set((a,x0) for a in range(y0,y1+1)) | set((a,x1) for a in range(y0,y1+1))
            if len(cells) != len(border) or set(cells) != border:
                continue
            # Composite side lengths fill with 2; prime side lengths fill with 7.
            side = y1 - y0 + 1
            prime = side >= 2 and all(side % d for d in range(2, int(side ** 0.5) + 1))
            fill = 7 if prime else 2
            if (y1-y0) != (x1-x0):
                fill = 7
            for a in range(y0+1,y1):
                for b in range(x0+1,x1):
                    if grid[a][b] == bg:
                        out[a][b] = fill
    return out", "exit_code": 0, "error": null}

